  // Model elements order {
  //TODO move to polyglot-common, or to org.apache.maven:maven-model
  private static List<String> ORDER_MODEL = new ArrayList<String>(Arrays.asList(
		  "modelEncoding",
          "modelVersion",
          "parent",
          "groupId",
          "artifactId",
          "version",
          "packaging",

          "name",
